    "category": "Führerschein",
    "image_url": "https://images.unsplash.com/photo-1517524008697-84bbe3c3fd98?w=800&auto=format&fit=crop&q=80",
    "sources": "Bundesamt für Strassen (ASTRA), Strassenverkehrsamt Schweiz",
